        assert!(parse_args(vec!["list".into(), "--nope".into()]).is_err());
        assert!(parse_args(vec!["--since".into()]).is_err(), "value-flag with no value");
        assert!(parse_args(vec!["--since".into(), "abc".into()]).is_err(), "non-integer epoch");
    }

