    #[test]
    fn the_cages_own_variables_cannot_be_rewritten_by_the_caller() {
        // PATH is the one that matters: `hook_env` sets it precisely because bash's post-`--clearenv`
        // default ends in `.`, the agent's own WRITABLE worktree. A caller-supplied PATH would hand
        // that back, which is the thing the isolation exists to prevent.
        let p = SessionPaths {
            root: PathBuf::from("/w"),
            home: Some(PathBuf::from("/home/agent")),
            agent_env: vec![
                ("PATH".into(), "/repo:/usr/bin".into()),
                ("HOME".into(), "/repo".into()),
                ("BSC_AGENT_PROVIDER".into(), "ollama".into()),
            ],
            ..Default::default()
        };
        let env = hook_env(&p);
        let paths_set: Vec<&String> = env.iter().filter(|(n, _)| n == "PATH").map(|(_, v)| v).collect();
        assert_eq!(paths_set.len(), 1, "exactly one PATH, not two");
        assert_eq!(paths_set[0], "/usr/local/bin:/usr/bin:/bin", "the CAGE's PATH wins");
        // Exactly one HOME too, and it is the cage's own — which here IS `/repo`, since this
        // fixture has no private tmpfs home. The property is "the caller cannot ADD a second or
        // shadow it", not that the value differs.
        assert_eq!(env.iter().filter(|(n, _)| n == "HOME").count(), 1);
        assert!(env.iter().any(|(n, v)| n == "HOME" && v == "/home/agent"), "the cage's HOME wins");
        // ...and a variable that genuinely belongs to the harness still crosses.
        assert!(env.iter().any(|(n, v)| n == "BSC_AGENT_PROVIDER" && v == "ollama"));
    }

