        // damage an `rm -rf /` can do is bounded to the agent's own (recoverable) worktree.
        let a = build(Role::Worker).spec.render().unwrap();
        let writable: Vec<&String> = a
            .iter()
            .enumerate()
            .filter(|(i, x)| *x == "--bind" && i + 2 < a.len())
            .map(|(i, _)| &a[i + 2])
