        let _lock = ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        std::env::remove_var("BSC_CHECKPOINT_DOC");
        assert!(!write_checkpoint_doc("body"), "no env ⇒ no write, and no panic");
        std::env::set_var("BSC_CHECKPOINT_DOC", "   ");
