import { describe, it, expect, vi } from "vitest";
import { applyDirectorNew, directorOnlyPlan, type DirectorRequest, type DirectorDeps } from "@/app/fleetDirectorBridge";

function req(over: Partial<DirectorRequest> = {}): DirectorRequest {
  return {
    id: "r1",
    projectKey: "studio-code",
    paneId: "studio-code:director",
    hubPath: "C:/hub/studio-code",
    ...over,
  };
}

function deps(over: Partial<DirectorDeps> = {}): DirectorDeps & { fleetStartProject: ReturnType<typeof vi.fn> } {
  return { fleetStartProject: vi.fn(), ...over } as never;
}

describe("directorOnlyPlan", () => {
  it("enables the director and launches NO worker streams", () => {
    const plan = directorOnlyPlan();
    expect(plan.director.enabled).toBe(true);
    expect(plan.streams).toEqual([]);
  });

  it("claims zero recommended workers rather than a number nothing backs", () => {
    // `recommended` drives what the UI says the fleet SHOULD be running. A create that launched one
    // pane while claiming a worker count would read as a fleet that had mostly failed to start.
    expect(directorOnlyPlan().recommended).toBe(0);
  });

  it("carries a reasoning that explains the single pane", () => {
    // It is what a later reader sees when asking why this build tab has one session in it.
    expect(directorOnlyPlan().reasoning).toMatch(/architect/i);
    expect(directorOnlyPlan().reasoning).toMatch(/no worker streams/i);
  });
});

describe("applyDirectorNew", () => {
  it("launches through fleetStartProject with the project key and the resolved hub path", () => {
    const d = deps();
    const ack = applyDirectorNew(req(), d);

    expect(ack).toEqual({ id: "r1", created: true });
    expect(d.fleetStartProject).toHaveBeenCalledTimes(1);
    const [name, plan, key, paths] = d.fleetStartProject.mock.calls[0];
    expect(name).toBe("studio-code");
    expect(key).toBe("studio-code");
    expect(plan.director.enabled).toBe(true);
    expect(plan.streams).toEqual([]);
    // The ABSOLUTE hub path from Rust (#905) — without it the launch falls back to the async
    // `bscBaseDir` mirror, which is empty at startup and drops the session at the user root.
    expect(paths).toEqual({ hubPath: "C:/hub/studio-code" });
  });

  it("passes hubPath as undefined rather than an empty string when Rust could not resolve one", () => {
    // `fleetStartProject` treats a falsy hubPath as "fall back to the mirror"; an empty STRING would
    // be a path it tries to use.
    const d = deps();
    applyDirectorNew(req({ hubPath: "" }), d);
    expect(d.fleetStartProject.mock.calls[0][3]).toEqual({ hubPath: undefined });
  });

  it("refuses an empty project key without launching anything", () => {
    const d = deps();
    for (const projectKey of ["", "   "]) {
      const ack = applyDirectorNew(req({ projectKey }), d);
      expect(ack.created).toBe(false);
      expect(ack.error).toBeTruthy();
    }
    expect(d.fleetStartProject).not.toHaveBeenCalled();
  });

  it("reports a throwing launch as a stated error rather than propagating it", () => {
    // A throw would strand the Rust waiter until its timeout and surface as "the frontend did not
    // create the director", sending someone to debug the wrong layer.
    const d = deps({ fleetStartProject: vi.fn(() => { throw new Error("no tab"); }) } as never);
    const ack = applyDirectorNew(req(), d);
    expect(ack.created).toBe(false);
    expect(ack.error).toContain("no tab");
  });

  it("always echoes the request id back, so the Rust waiter is never stranded", () => {
    const d = deps({ fleetStartProject: vi.fn(() => { throw new Error("x"); }) } as never);
    expect(applyDirectorNew(req({ id: "corr-9" }), d).id).toBe("corr-9");
    expect(applyDirectorNew(req({ id: "corr-9", projectKey: "" }), deps()).id).toBe("corr-9");
  });

  it("never reports created:true on a path that did not launch", () => {
    // The one invariant the ack carries: the kickoff is already on disk by the time this runs, so a
    // false success leaves a project looking seeded with no session behind it.
    const failing = deps({ fleetStartProject: vi.fn(() => { throw new Error("x"); }) } as never);
    expect(applyDirectorNew(req(), failing).created).toBe(false);
    expect(applyDirectorNew(req({ projectKey: "" }), deps()).created).toBe(false);
  });
});

implementations.code:
// useFleetDirectorBridge (#architect-creates-a-director-with-discovery) — apply a
// `bsc fleet director new` request and ACK it.
//
// THE ROUND TRIP
//   bsc fleet director new <key> → request file → Rust watcher (resolves the project, refuses a live
//   director, seeds prompts/director-kickoff.md) → `bsc://fleet-director` → HERE → fleetStartProject
//   → `fleet_director_ack`
//
// A thin adapter: the DECISION lives in `fleetDirectorBridge.ts`, unit-testable without Tauri.
//
// THIS IS NOT AN INJECTION PATH. The director's context is BAKED INTO THE LAUNCH as claude's
// initial-message argument — the same delivery the kickoff doc always used. Nothing is typed into a
// running session, and `injectCallers.test.ts` stays green on its empty set.
//
// WHY THE DOC IS READ HERE RATHER THAN AT LAUNCH (#the-director-launches-with-no-kickoff-prompt)
// `fleetStartProject` seeds the kickoff as a doc PATH, which TerminalView resolves once inside its
// launch effect. That is the route whose silent-loss failure is documented on the `startupPrompt`
// prop — the one that left every debug session "a bare `claude` with nothing to do" until debug and
// studio sessions were migrated off it. The director never was.
//
// So this resolves the doc to text FIRST and hands it to `applyDirectorNew`, which seeds it before any
// pane exists. `read_document` failing is not fatal: the launch proceeds and the doc route stays as
// the fallback, because a director delivered the old way beats no director at all.
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { log } from "@/shared/lib/core/log";
import { scriptDocRelpath } from "@/features/planner/session/planningSession";
import { sanitizeProjectKey } from "@/shared/lib/core/projectPaths";
import { applyDirectorNew, type DirectorRequest, type DirectorAck } from "@/app/fleetDirectorBridge";

/** The hub-relative kickoff every director launch reads, resolved in Rust before the emit. */
const KICKOFF_RELPATH = "prompts/director-kickoff.md";

/** Listen for `bsc://fleet-director` and launch it. Mounted once by the shell. */
export function useFleetDirectorBridge(): void {
  useEffect(() => {
    let disposed = false;
    const un = listen<DirectorRequest>("bsc://fleet-director", (e) => {
      const req = e.payload;
      void (async () => {
        // Resolve the kickoff BEFORE the launch. A failure is logged and carried as `undefined` — the
        // launch still happens and falls back to the doc route rather than refusing to create the
        // director the architect asked for.
        let kickoffText: string | undefined;
        try {
          const relpath = scriptDocRelpath(sanitizeProjectKey(req.projectKey ?? ""), KICKOFF_RELPATH);
          const text = await invoke<string>("read_document", { relpath });
          kickoffText = typeof text === "string" && text.trim() ? text : undefined;
          if (!kickoffText) log.warn(`fleet director ${req.id}: ${relpath} is empty — falling back to the doc route`);
        } catch (err) {
          log.warn(`fleet director ${req.id}: kickoff read failed (${String(err)}) — falling back to the doc route`);
        }

        let ack: DirectorAck;
        try {
          ack = applyDirectorNew(
            req,
            {
              // Read off a LIVE getState, not a captured snapshot — zustand hands out a new object per
              // update, so a stale closure could launch against an older tab list.
              fleetStartProject: (name, fleet, key, paths) =>
                useAppStore.getState().fleetStartProject(name, fleet, key, paths),
              seedStartupPromptText: (paneId, text) =>
                useAppStore.setState((s) => ({
                  paneStartupPromptText: { ...s.paneStartupPromptText, [paneId]: text },
                })),
            },
            kickoffText,
          );
        } catch (err) {
          ack = {
            id: req.id,
            error: `fleet director threw: ${err instanceof Error ? err.message : String(err)}`,
            created: false,
          };
          log.error(`fleet director ${req.id} threw: ${String(err)}`);
        }
        void invoke("fleet_director_ack", { ack: { ...ack, id: req.id } }).catch((e2) => {
          // Nothing left to do — the caller will time out. Log it so the cause isn't a mystery.
          log.error(`fleet_director_ack failed for ${req.id}: ${String(e2)}`);
        });
      })();
    });
    return () => {
      disposed = true;
      void un.then((f) => {
        if (disposed) f();
      });
    };
  }, []);
}
